package device

import (
	"strconv"
	"strings"
	"time"
)

// DeviceID is a unique identifier for a device (UUID, generated by the system).
type DeviceID string

// Source identifies the integration a device was discovered through, and
// doubles as the integration's provider id in the GraphQL API.
type Source string

const (
	// SourceZigbee2MQTT covers Zigbee devices bridged onto MQTT by zigbee2mqtt.
	SourceZigbee2MQTT Source = "zigbee2mqtt"
	// SourceTuya covers devices reached through the Tuya cloud API.
	SourceTuya Source = "tuya"
)

// DeviceType classifies a device by its primary function.
type DeviceType string

const (
	// Light represents a controllable light device.
	Light DeviceType = "light"
	// Sensor represents a device that reports environmental readings.
	Sensor DeviceType = "sensor"
	// Button represents an input device that reports discrete action events
	// (e.g. single / double / hold) without an on/off state of its own.
	Button DeviceType = "button"
	// Plug represents a switchable outlet, usually with on/off control and
	// often with power metering (power, voltage, current, energy).
	Plug DeviceType = "plug"
	// Climate represents a heating/cooling device with thermostat-like controls.
	Climate DeviceType = "climate"
	// Speaker represents an audio output device.
	Speaker DeviceType = "speaker"
	// Hub represents a network's point of entry (a Zigbee coordinator, a
	// Thread border router): a real box on the wall that belongs to a room
	// and a spot on the floor plan, but takes no commands and reports no
	// state, so EnabledDevices keeps it out of every command and watch path.
	Hub DeviceType = "hub"
	// Unknown represents a device whose type could not be determined.
	Unknown DeviceType = "unknown"
)

// ControlledLoadRole describes what a switchable plug powers.
type ControlledLoadRole string

const (
	ControlledLoadRoleAppliance ControlledLoadRole = "appliance"
	ControlledLoadRoleLight     ControlledLoadRole = "light"
)

// ContactRole describes what a contact-capable device observes.
type ContactRole string

const (
	ContactRoleGeneral ContactRole = "general"
	ContactRoleDoor    ContactRole = "door"
	ContactRoleWindow  ContactRole = "window"
)

// DeviceRoles contains the user-owned semantic roles applicable to a device.
// A nil field means the role category does not apply to that device.
type DeviceRoles struct {
	ControlledLoad *ControlledLoadRole `json:"controlledLoad,omitempty"`
	Contact        *ContactRole        `json:"contact,omitempty"`
}

// Capability constants for known device capabilities.
const (
	CapOnOff             = "on_off"
	CapBrightness        = "brightness"
	CapColorTemp         = "color_temp"
	CapColor             = "color"
	CapTemperature       = "temperature"
	CapHumidity          = "humidity"
	CapPressure          = "pressure"
	CapIlluminance       = "illuminance"
	CapOccupancy         = "occupancy"
	CapContact           = "contact"
	CapOrientation       = "orientation"
	CapDevicePosture     = "device_posture"
	CapLinkQuality       = "link_quality"
	CapBattery           = "battery"
	CapAction            = "action"
	CapEffect            = "effect"
	CapPower             = "power"
	CapVoltage           = "voltage"
	CapCurrent           = "current"
	CapEnergy            = "energy"
	CapTargetTemperature = "target_temperature"
	CapHvacMode          = "hvac_mode"
	CapFanMode           = "fan_mode"
	CapSwing             = "swing"
)

// CapabilityAccess is the access bitmask reported by an adapter.
type CapabilityAccess int

const (
	CapabilityAccessState CapabilityAccess = 1
	CapabilityAccessSet   CapabilityAccess = 2
	CapabilityAccessGet   CapabilityAccess = 4
)

// CapabilityCategory separates live state, device configuration, and
// diagnostic readings without relying on capability names.
type CapabilityCategory string

const (
	CapabilityCategoryState         CapabilityCategory = "state"
	CapabilityCategoryConfiguration CapabilityCategory = "configuration"
	CapabilityCategoryDiagnostic    CapabilityCategory = "diagnostic"
)

// Capability describes a single device capability with optional rich metadata
// extracted from the protocol adapter (e.g. zigbee2mqtt exposes).
type Capability struct {
	Name        string             `json:"name"`
	Type        string             `json:"type"`
	Label       string             `json:"label,omitempty"`
	Description string             `json:"description,omitempty"`
	Category    CapabilityCategory `json:"category,omitempty"`
	Values      []string           `json:"values,omitempty"`
	ValueMin    *float64           `json:"valueMin,omitempty"`
	ValueMax    *float64           `json:"valueMax,omitempty"`
	Unit        string             `json:"unit,omitempty"`
	Access      CapabilityAccess   `json:"access"`
}

// ReportsValue reports whether the adapter publishes this capability.
func (c Capability) ReportsValue() bool {
	return c.Access&CapabilityAccessState != 0
}

// CanSet reports whether the capability accepts writes.
func (c Capability) CanSet() bool {
	return c.Access&CapabilityAccessSet != 0
}

// CanGet reports whether the capability accepts explicit reads.
func (c Capability) CanGet() bool {
	return c.Access&CapabilityAccessGet != 0
}

// EffectiveCategory treats an omitted category as ordinary state.
func (c Capability) EffectiveCategory() CapabilityCategory {
	if c.Category == "" {
		return CapabilityCategoryState
	}
	return c.Category
}

// Device is the protocol-agnostic representation of a home automation device.
type Device struct {
	ID DeviceID `json:"id"`
	// Name is the user's override, nil when unset. FriendlyName is what the
	// integration reports and is refreshed on every adapter sync. Read
	// DisplayName rather than either field directly.
	Name         *string `json:"name,omitempty"`
	FriendlyName string  `json:"friendlyName"`
	Icon         *string `json:"icon,omitempty"`
	// DisplayColor is the colour the floor plan gives a device that reports
	// none of its own, as a #rrggbb string; nil leaves it to the map default.
	DisplayColor *string `json:"displayColor,omitempty"`
	// DisplayBrightness is how bright such a device shows, 0-254; nil is full.
	DisplayBrightness *int64       `json:"displayBrightness,omitempty"`
	Source            Source       `json:"source"`
	Type              DeviceType   `json:"type"`
	Roles             DeviceRoles  `json:"roles"`
	Capabilities      []Capability `json:"capabilities"`
	Available         bool         `json:"available"`
	Removed           bool         `json:"removed"`
	// Disabled excludes the device from every path that commands or watches it
	// (scenes, automations, effects, staleness alarms) while keeping its row and
	// its detail page. For seasonal hardware that is unplugged but not gone.
	Disabled bool `json:"disabled"`
	// Seen is false between a device being discovered and the user opening the
	// device list, which is what marks it as new in the UI.
	Seen     bool      `json:"seen"`
	LastSeen time.Time `json:"lastSeen"`
}

// DisplayName resolves the name to show for a device: the user's override, then
// the name its integration reports, then the id. The id is always present, so
// this never returns empty. Every caller that renders or matches a device name
// goes through here.
func (d Device) DisplayName() string {
	if d.Name != nil && *d.Name != "" {
		return *d.Name
	}
	if d.FriendlyName != "" {
		return d.FriendlyName
	}
	return string(d.ID)
}

// AdapterFingerprint summarises the adapter-owned fields that belong in the
// database: the friendly name, the type, and the capability set. Adapters
// compare it across syncs so a re-report that changed nothing publishes nothing.
// Runtime fields (availability, last seen, reported state) are deliberately
// absent, because they have their own events and would make every sync look
// like a change.
func AdapterFingerprint(d Device) string {
	var b strings.Builder
	b.WriteString(d.FriendlyName)
	b.WriteByte(0)
	b.WriteString(string(d.Type))
	for _, c := range d.Capabilities {
		b.WriteByte(0)
		b.WriteString(c.Name)
		b.WriteByte(':')
		b.WriteString(c.Type)
		b.WriteByte(':')
		b.WriteString(strconv.Itoa(int(c.Access)))
		b.WriteByte(':')
		b.WriteString(string(c.EffectiveCategory()))
		b.WriteByte(':')
		b.WriteString(c.Label)
		b.WriteByte(':')
		b.WriteString(c.Description)
		b.WriteByte(':')
		b.WriteString(c.Unit)
		b.WriteByte(':')
		if c.ValueMin != nil {
			b.WriteString(strconv.FormatFloat(*c.ValueMin, 'g', -1, 64))
		}
		b.WriteByte(':')
		if c.ValueMax != nil {
			b.WriteString(strconv.FormatFloat(*c.ValueMax, 'g', -1, 64))
		}
		for _, v := range c.Values {
			b.WriteByte(',')
			b.WriteString(v)
		}
	}
	return b.String()
}

// EnabledDevices returns the subset of devs that command fan-out, selector
// evaluation and health monitoring operate on: not removed, not disabled, and
// not a hub — a hub is placeable and room-assignable but never commanded,
// watched or health-checked. Display and history paths use the unfiltered
// list.
func EnabledDevices(devs []Device) []Device {
	out := make([]Device, 0, len(devs))
	for _, d := range devs {
		if d.Removed || d.Disabled || d.Type == Hub {
			continue
		}
		out = append(out, d)
	}
	return out
}
